"use strict";

/* ---------- 1. Data (temperatures always stored in Celsius) ---------- */
const sampleWeather = {
  current: {
    city: "Hyderabad",
    temp: 32,
    condition: "partly cloudy",
    wind: 12,      // km/h
    humidity: 65   // %
  },
  daily: [
    { date: "2026-11-30", condition: "sunny",         max: 34, min: 22 },
    { date: "2026-12-01", condition: "partly cloudy", max: 33, min: 21 },
    { date: "2026-12-02", condition: "rain",          max: 31, min: 20 },
    { date: "2026-12-03", condition: "sunny",         max: 32, min: 21 },
    { date: "2026-12-04", condition: "thunderstorm",  max: 30, min: 20 },
    { date: "2026-12-05", condition: "rain",          max: 29, min: 19 },
    { date: "2026-12-06", condition: "partly cloudy", max: 31, min: 20 }
  ]
};

/* ---------- Icons (embedded in code, no separate image files) ---------- */
const ICONS = {
  "sunny": "data:image/png;base64,",
  "partly-cloudy": "data:image/png;base64,",
  "partly-cloudy-large": "data:image/png;base64,",
  "rain": "data:image/png;base64,",
  "thunderstorm": "data:image/png;base64,"
};

/* ---------- 2. State ---------- */
let unit = "C"; // "C" or "F"

/* ---------- 3. DOM references ---------- */
const searchForm = document.querySelector(".search-form");
const cityInput = document.querySelector("#city-input");
const formMessage = document.querySelector("#form-message");
const unitToggle = document.querySelector("#unit-toggle");

const currentIcon = document.querySelector(".current-icon");
const currentCity = document.querySelector(".current-city");
const currentTemp = document.querySelector(".current-temp");
const currentCondition = document.querySelector(".current-condition");
const currentWind = document.querySelector(".current-wind");
const currentHumidity = document.querySelector(".current-humidity");
const forecastRow = document.querySelector(".forecast-row");

/* ---------- 4. Helpers ---------- */
function toFahrenheit(c) {
  return c * 9 / 5 + 32;
}

// Convert only when displaying, so stored values never drift.
function formatTemp(c) {
  const value = unit === "F" ? toFahrenheit(c) : c;
  return `${Math.round(value)}°${unit}`;
}

function normalize(condition) {
  return String(condition).trim().toLowerCase();
}

function getWeatherEmoji(condition) {
  const emojis = {
    "sunny": "☀️",
    "partly cloudy": "⛅",
    "cloudy": "☁️",
    "rain": "🌧️",
    "thunderstorm": "⛈️"
  };
  return emojis[normalize(condition)] || "🌡️";
}

// Icons live inside this file (ICONS), so no extra image files are needed
function getIconSrc(condition, large = false) {
  const names = {
    "sunny": "sunny",
    "partly cloudy": "partly-cloudy",
    "cloudy": "partly-cloudy",
    "rain": "rain",
    "thunderstorm": "thunderstorm"
  };
  const name = names[normalize(condition)] || "partly-cloudy";
  if (large && name === "partly-cloudy") return ICONS["partly-cloudy-large"];
  return ICONS[name];
}

function titleCase(text) {
  return normalize(text).replace(/\b\w/g, (ch) => ch.toUpperCase());
}

function getDayName(dateString) {
  // "T00:00:00" makes the date local, so the weekday never shifts by timezone
  return new Date(`${dateString}T00:00:00`).toLocaleDateString("en-IN", { weekday: "short" });
}

/* ---------- 5. Rendering ---------- */
function renderCurrent(data) {
  currentIcon.src = getIconSrc(data.condition, true);
  currentIcon.alt = titleCase(data.condition);
  currentCity.textContent = data.city;
  currentTemp.textContent = formatTemp(data.temp);
  currentCondition.textContent = `${getWeatherEmoji(data.condition)} ${titleCase(data.condition)}`;
  currentWind.textContent = `${data.wind} km/h`;
  currentHumidity.textContent = `${data.humidity}%`;
}

function renderForecast(days) {
  forecastRow.innerHTML = days
    .map(
      (day) => `
        <li class="forecast-card">
          <h3 class="forecast-day">${getDayName(day.date)}</h3>
          <img class="forecast-icon" src="${getIconSrc(day.condition)}" alt="${titleCase(day.condition)}">
          <p class="forecast-max">${formatTemp(day.max)}</p>
          <p class="forecast-min">${formatTemp(day.min)}</p>
        </li>`
    )
    .join("");
}

// Stretch goal: tint the page background by current condition
function applyTheme(condition) {
  const key = normalize(condition).replace(/\s+/g, "-");
  document.body.dataset.weather = key;
}

function render() {
  renderCurrent(sampleWeather.current);
  renderForecast(sampleWeather.daily);
  applyTheme(sampleWeather.current.condition);
  unitToggle.textContent = unit === "C" ? "Switch to °F" : "Switch to °C";
}

/* ---------- 6. Events ---------- */
unitToggle.addEventListener("click", () => {
  unit = unit === "C" ? "F" : "C";
  render();
});

searchForm.addEventListener("submit", (event) => {
  event.preventDefault();
  const city = cityInput.value.trim();

  if (!city) {
    formMessage.textContent = "Please enter a city name.";
    cityInput.focus();
    return;
  }

  formMessage.textContent = "";
  sampleWeather.current.city = city; // real API data comes in a later week
  render();
});

cityInput.addEventListener("input", () => {
  formMessage.textContent = "";
});

render();
